import{_ as a,c as r,o as l,a2 as o}from"./chunks/framework.CzULAunO.js";const d=JSON.parse('{"title":"刷课","description":"","frontmatter":{},"headers":[],"relativePath":"docs/general-skills/qi-ji-yin-qiao/pointless-courses.md","filePath":"docs/general-skills/qi-ji-yin-qiao/pointless-courses.md","lastUpdated":1766652908000}'),t={name:"docs/general-skills/qi-ji-yin-qiao/pointless-courses.md"};function i(s,e,n,c,p,h){return l(),r("div",null,e[0]||(e[0]=[o('<h1 id="刷课" tabindex="-1"><strong>刷课</strong> <a class="header-anchor" href="#刷课" aria-label="Permalink to &quot;**刷课**&quot;">​</a></h1><blockquote><p>安全教育，心理健康...无论是否有用，它都占据了很多时间，而且大概率是在课堂上，导致同学们因人机验证，视频跳转等分散注意力。本文为读者提供一种能在相同的时间内，做更有意义的事情的机会。</p></blockquote><blockquote><p>刷课尤其是高倍速，半夜刷课等有被抓包风险，please try at your own risk. 考虑到您的学业，学校对刷课的处理等因素，不推荐用于专业课程。</p></blockquote><p>目前笔者见过两种刷课方式，直接发送课程完成的请求和使用脚本挂机并完成相关弹窗检测。本文仅涵盖部分笔者遇到的课程，欢迎各位补充和指正。</p><h2 id="安全教育-安全微伴" tabindex="-1">安全教育（安全微伴） <a class="header-anchor" href="#安全教育-安全微伴" aria-label="Permalink to &quot;安全教育（安全微伴）&quot;">​</a></h2><p><a href="https://github.com/hangone/WeBan" target="_blank" rel="noreferrer">WeBan</a></p><ul><li>实现了课程学习和根据题库自动考试，支持多用户多线程运行（配置 config.json），自动验证码识别（需要源码运行，安装 ddddocr）。</li><li>项目文档指南较容易理解。运行前后会自动合并题库，如果一次没满分可以再考一次。可将 answer/answer.json 文件提交 PR 一起完善题库。</li><li>可调节每节课学习时间，单位（秒），默认 15 秒</li></ul><h2 id="宪法小卫士" tabindex="-1">宪法小卫士 <a class="header-anchor" href="#宪法小卫士" aria-label="Permalink to &quot;宪法小卫士&quot;">​</a></h2><p><a href="https://greasyfork.org/zh-CN/scripts/430038-%E6%99%AE%E6%B3%95%E7%BD%91-%E5%AE%AA%E6%B3%95%E5%B0%8F%E5%8D%AB%E5%A3%AB-%E8%AF%BE%E5%90%8E%E7%BB%83%E4%B9%A0-%E8%80%83%E8%AF%95%E8%87%AA%E5%8A%A8%E7%AD%94%E9%A2%98" target="_blank" rel="noreferrer">普法网（宪法小卫士）课后练习、考试自动答题</a></p><ul><li>该课程较短，是否使用请自行决定</li></ul><h2 id="智慧树等网课平台" tabindex="-1">智慧树等网课平台 <a class="header-anchor" href="#智慧树等网课平台" aria-label="Permalink to &quot;智慧树等网课平台&quot;">​</a></h2><p><a href="https://github.com/VermiIIi0n/fuckZHS" target="_blank" rel="noreferrer">fuckZHS</a></p><ul><li>支持智慧树网课</li><li>可设定刷课时长</li><li>python 脚本，无需位于前台</li><li>自动回答弹窗问题</li></ul><p><a href="https://docs.ocsjs.com/docs/quickly-start" target="_blank" rel="noreferrer">ocsjs</a></p><ul><li>支持智慧树，学习通等网课</li><li>浏览器界面需要缩放合适，部分平台可能需要位于前台</li></ul><p><a href="https://github.com/yatori-dev/yatori-go-console" target="_blank" rel="noreferrer">Yatori-go-console</a></p><ul><li>支持英华学堂，学习通等平台</li><li>独立软件、支持 docker 容器化部署</li></ul>',17)]))}const f=a(t,[["render",i]]);export{d as __pageData,f as default};
